//! The precision oracle replays the same formula in binary64 with propagated FP32 store intervals.
const std = @import("std");
const edit = @import("../src/families/flashnext/geometry_source.zig");
pub fn generate(a: std.mem.Allocator) ![]const u8 {
    var text = try std.mem.concat(a, u8, &.{ @embedFile("../kernels/common/living_rows.h"), "\n", @embedFile("../kernels/common/living_gdn.h"), "\n", @embedFile("../kernels/common/living_qsa.h"), "\n", @embedFile("../kernels/common/living_gemma.h") });
    const round = try edit.function(text, "float lw_round(");
    text = try edit.once(a, text, round, "LW_INLINE float lw_round(float x) { return lw_bf_ref(x); }");
    const store = try edit.function(text, "void lw_store(");
    text = try edit.once(a, text, store, "LW_INLINE void lw_store(LwParams meta,LW_DEV unsigned char* p,unsigned i,float x) { ((float*)p)[i]=lw_bf_ref(x); }");
    text = try std.mem.replaceOwned(u8, a, text, "float", "LwReference");
    text = try std.mem.replaceOwned(u8, a, text, "lw_LwReference", "lw_float");
    text = try std.mem.replaceOwned(u8, a, text, "out[i]=add?out[i]+v:v;", "if(add)out[i]+=v;else out[i]=v;");
    const cached = try edit.function(text, "LwReference lw_gdn_y(");
    const uncached = try std.mem.replaceOwned(u8, a, cached, "lw_gdn_y(", "lw_gdn_y_uncached(");
    const wrapper = "\nstatic LwReference* y_cache=nullptr;static unsigned char* y_seen=nullptr;\nstatic void cache_clear(){free(y_cache);free(y_seen);y_cache=nullptr;y_seen=nullptr;}\nstatic bool cache_init(unsigned n){cache_clear();y_cache=(LwReference*)malloc(n*sizeof(LwReference));y_seen=(unsigned char*)calloc(n,1);return y_cache&&y_seen;}\nLW_INLINE LwReference lw_gdn_y(const unsigned char* qk,const unsigned char* state,LwParams p,unsigned row,unsigned head,unsigned value){const unsigned at=(row*p.u[2]+head)*128+value;if(!y_seen[at]){const auto v=lw_gdn_y_uncached(qk,state,p,row,head,value).resolved();memcpy(y_cache+at,&v,sizeof(v));y_seen[at]=1;}return y_cache[at];}\n";
    text = try edit.once(a, text, cached, try std.mem.concat(a, u8, &.{ uncached, wrapper }));
    var out: std.Io.Writer.Allocating = .init(a);
    try out.writer.writeAll(@embedFile("../tests/qwen4/living_reference.h"));
    try out.writer.writeAll("\n#undef TF_LIVING_ROWS\n#undef TF_LIVING_GDN\n#undef TF_LIVING_GEMMA\n#undef TF_LIVING_QSA\n#undef LW_TANH\n#undef LW_ACC\n#undef LW_ISNAN\n#undef LW_INLINE\n#undef LW_DEV\n#undef LW_BITS_FLOAT\n#undef LW_FLOAT_BITS\n#undef LW_EXP\n#undef LW_ABS\n#undef LW_SQRT\n#undef LW_LOG\n#undef LW_SIN\n#undef LW_COS\n#undef LW_INFINITY\n#undef LW_FMA\n#define LW_ACC(p,target,value) ((target)+=(value))\n#define LW_ISNAN(x) __builtin_isnan((x).value)\n#define LW_DEV\n#define LW_INLINE inline\n#define LW_BITS_FLOAT(x) LwReference(lw_ref_bits(x))\n#define LW_FLOAT_BITS(x) lw_ref_float_bits(x)\n#define LW_TANH lw_tanh\n#define LW_EXP lw_exp\n#define LW_ABS lw_abs\n#define LW_SQRT lw_sqrt\n#define LW_LOG lw_log\n#define LW_SIN lw_sin\n#define LW_COS lw_cos\n#define LW_INFINITY LwReference(INFINITY)\n#define LW_FMA lw_fma\nnamespace lw_reference {\n");
    try out.writer.writeAll(text);
    try out.writer.writeAll("\n}\nextern \"C\" bool tf_living_reference(unsigned kind,unsigned op,LwParams source,unsigned char** inputs,const unsigned* types,const unsigned* counts,LwReference** outputs,unsigned accumulator,unsigned order) {\n  lw_terms_clear();lw_accumulator=accumulator;lw_order=order;lw_memory_failure=false; if(kind==1&&!lw_reference::cache_init(source.u[0]*source.u[2]*128))return false;\n  unsigned char* views[11]; LwReference* owned[8]={}; lw_reference::LwParams p; memcpy(p.u,source.u,sizeof(p.u)); for(unsigned i=0;i<4;i++)p.f[i]=LwReference(source.f[i]);\n  for(unsigned i=0;i<11;i++){if(i>=8){views[i]=(unsigned char*)outputs[i-8];for(unsigned j=0;j<counts[i];j++){const LwReference zero(0);memcpy(outputs[i-8]+j,&zero,sizeof(zero));}}else if(types[i]==0){owned[i]=(LwReference*)malloc(counts[i]*sizeof(LwReference));if(!owned[i]&&counts[i]){for(unsigned z=0;z<i;z++)free(owned[z]);return false;}for(unsigned j=0;j<counts[i];j++){const LwReference v(((float*)inputs[i])[j]);memcpy(owned[i]+j,&v,sizeof(v));}views[i]=(unsigned char*)owned[i];}else views[i]=inputs[i];}\n  for(unsigned i=0;i<p.u[15];i++){if(kind==0)lw_reference::lw_rows(op,i,p,views[0],views[1],views[2],views[3],views[4],views[5],views[6],views[7],views[8],views[9],views[10]);else if(kind==1)lw_reference::lw_gdn(op,i,p,views[0],views[1],views[2],views[3],views[4],views[5],views[6],views[7],views[8],views[9],views[10]);else if(kind==2)lw_reference::lw_qsa(op,i,p,views[0],views[1],views[2],views[3],views[4],views[5],views[6],views[7],views[8],views[9],views[10]);else lw_reference::lw_gemma(op,i,p,views[0],views[1],views[2],views[3],views[4],views[5],views[6],views[7],views[8],views[9],views[10]);}\n  for(unsigned i=0;i<3;i++)for(unsigned j=0;j<counts[i+8];j++)outputs[i][j]=outputs[i][j].resolved();for(unsigned i=0;i<8;i++)free(owned[i]);lw_reference::cache_clear();lw_terms_clear();return !lw_memory_failure;\n}\n");
    return out.toOwnedSlice();
}
